package cn.nebulaedata.cccs.nebuwork.backend.api.knowledge;

import cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiException;
import cn.nebulaedata.cccs.nebuwork.backend.api.identity.RequestIdentity;
import cn.nebulaedata.cccs.nebuwork.backend.api.identity.SessionFilter;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.springframework.stereotype.Service;
import org.springframework.web.bind.annotation.*;
import javax.servlet.http.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.regex.*;
import static cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiSupport.map;
import static cn.nebulaedata.cccs.nebuwork.backend.api.knowledge.KnowledgeValues.*;
import static cn.nebulaedata.cccs.nebuwork.backend.api.knowledge.NebulaeV101RestDriver.data;
import static cn.nebulaedata.cccs.nebuwork.backend.api.knowledge.KnowledgeRestClient.segment;

/** An authenticated, finite V101 API surface. The browser never selects an upstream URL. */
@Service
public class KnowledgeV101Gateway {
    private final KnowledgeAccess access;private final KnowledgeService knowledge;private final NebulaeV101RestDriver driver;private final KnowledgeOperations operations;private final ObjectMapper json;private final SessionFilter sessions;
    public KnowledgeV101Gateway(KnowledgeAccess access,KnowledgeService knowledge,NebulaeV101RestDriver driver,KnowledgeOperations operations,ObjectMapper json,SessionFilter sessions){this.access=access;this.knowledge=knowledge;this.driver=driver;this.operations=operations;this.json=json;this.sessions=sessions;}
    Map<String,Object> connection(String actor,String id){Map<String,Object> c=access.connection(id);if(!NebulaeV101RestDriver.ID.equals(c.get("driver"))||!bool(c.get("enabled"))||!access.admin(actor)&&!access.visible(actor,c))throw new ApiException(404,"V101 连接不可用");return c;}
    private JsonNode get(Map<String,Object> c,String path){return driver.client.execute(string(c,"endpoint"),knowledge.headers(c),s->data(s.request("GET",path,null)));}
    private Set<String> permitted(String actor,Map<String,Object> c){Set<String> ids=new LinkedHashSet<>();for(Map<String,Object> r:access.jdbc().queryForList("SELECT collection_id FROM nw_knowledge_library WHERE service_key=?",access.serviceKey(c)))if(access.allowed(actor,c,string(r,"collection_id"),false))ids.add(string(r,"collection_id"));return ids;}
    private final class Grant {final String actor;final Map<String,Object> c;final Set<String> scopes=new LinkedHashSet<>();boolean admin;Grant(String actor,Map<String,Object> c){this.actor=actor;this.c=c;}void kb(String id,boolean write){access.require(actor,c,id,write);scopes.add(id);}void administrator(){access.requireAdmin(actor);admin=true;}boolean live(HttpServletRequest request){try{Map<String,Object> now=connection(actor,string(c,"id"));if(!sessions.stillAuthenticated(request,actor))return false;if(admin)access.requireAdmin(actor);for(String kb:scopes)access.require(actor,now,kb,false);return true;}catch(Exception denied){return false;}}}
    private JsonNode owned(Grant g,String kind,String id){Map<String,Object> row=access.one("SELECT * FROM nw_knowledge_v101_resource WHERE service_key=? AND owner_id=? AND kind=? AND remote_id=?",access.serviceKey(g.c),g.actor,kind,id);if(row==null||row.isEmpty())throw new ApiException(404,"V101 资源不属于当前账号");try{JsonNode scope=json.readTree(string(row,"scope_json"));for(JsonNode kb:scope)g.kb(kb.asText(),false);if(row.get("parent_id")!=null&&!string(row,"parent_id").isEmpty())owned(g,"qa-session",string(row,"parent_id"));return scope;}catch(IOException e){throw new ApiException(500,"V101 资源范围记录无效");}}
    private void save(Grant g,String kind,String id,String parent){if(id==null||id.isEmpty())return;Set<String> scopes=new LinkedHashSet<>(g.scopes);Map<String,Object> old=access.one("SELECT * FROM nw_knowledge_v101_resource WHERE service_key=? AND kind=? AND remote_id=?",access.serviceKey(g.c),kind,id);if(old!=null&&!g.actor.equals(old.get("owner_id")))throw new ApiException(409,"V101 资源已有其他归属");try{if(old!=null)for(JsonNode kb:json.readTree(string(old,"scope_json")))scopes.add(kb.asText());access.jdbc().update("INSERT INTO nw_knowledge_v101_resource(id,service_key,owner_id,kind,remote_id,parent_id,scope_json) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE scope_json=VALUES(scope_json)",id("kv101"),access.serviceKey(g.c),g.actor,kind,id,parent,json.writeValueAsString(scopes));}catch(IOException e){throw new ApiException(500,"无法登记 V101 资源");}}
    private void bodyScopes(Grant g,JsonNode body){for(JsonNode id:body.path("knowledge_base_ids"))g.kb(id.asText(),false);for(JsonNode id:body.path("knowledge_ids"))g.kb(get(g.c,"/knowledge/"+segment(id.asText())).path("knowledge_base_id").asText(),false);if(!body.path("knowledge_base_id").asText().isEmpty())g.kb(body.path("knowledge_base_id").asText(),false);}
    private String resourceKB(Grant g,String kind,String id){JsonNode value;if("knowledge".equals(kind))value=get(g.c,"/knowledge/"+segment(id));else if("sources".equals(kind))value=get(g.c,"/sources/"+segment(id));else if("images".equals(kind)||"preview-assets".equals(kind)){value=get(g.c,"/assets/"+segment(id)+"/metadata");}else if("uploads".equals(kind))value=get(g.c,"/uploads/"+segment(id));else if("tasks".equals(kind))value=get(g.c,"/tasks/"+segment(id));else{value=get(g.c,"/extractions/"+segment(id));if(value.path("knowledge_base_id").asText().isEmpty())value=get(g.c,"/knowledge/"+segment(value.path("knowledge_id").asText()));}String kb=value.path("knowledge_base_id").asText("");if(kb.isEmpty()&&"tasks".equals(kind))kb=value.path("config").path("knowledge_base_id").asText("");return kb;}
    static boolean readCall(String method,String path){return "GET".equals(method)||"HEAD".equals(method)||"POST".equals(method)&&(path.equals("/search")||path.matches("/search/(keyword|vector|hybrid|graph|wiki|image-text|image-vector|multi)")||path.matches("/knowledge-bases/[^/]+/(search|graph/query)")||path.matches("/knowledge/[^/]+/read")||path.equals("/sources/resolve-batch")||path.matches("/(processing-config/(resolve|suggest)|chunker/preview|image-pipelines/validate)"));}
    static boolean allowedRoute(String method,String path){
        if(!Arrays.asList("GET","HEAD","POST","PUT","PATCH","DELETE").contains(method))return false;
        String id="[A-Za-z0-9_-]{1,128}";
        return path.matches("/knowledge-bases(?:/"+id+"(?:/(?:stats|processing|tasks(?:/(?:stats|cancel|retry-failed|pause|resume))?|capabilities|duplicate|rebuild|search|wiki/(?:folders(?:/"+id+")?|stats|graph|rebuild|rebuild-links|pages(?:/"+id+"(?:/(?:revert|revisions))?)?)|graph(?:/(?:query|stats|rebuild|evidence/"+id+"))?|knowledge(?:/(?:files?|manual|url|folders(?:/"+id+")?))?|uploads|images))?)?")
            ||path.matches("/knowledge/"+id+"(?:/(?:versions|content|chunks|stages|outline(?:/rebuild)?|download|preview(?:/(?:manifest|rebuild))?|media(?:/(?:transcript|frames|reprocess))?|transcript|frames|images(?:/rebuild)?|reparse|cancel-parse|read|subtitles|sheets(?:/"+id+"/cells)?|spreadsheet-settings|related/stats|wiki/(?:pages(?:/"+id+")?|graph)|graph|extractions(?:/sections)?))?")
            ||path.matches("/(?:sources/(?:"+id+"|resolve-batch)|images/"+id+"(?:/(?:content|derivatives|preprocess|reprocess))?|preview-assets/"+id+"|uploads/(?:policy|"+id+"(?:/(?:complete|parts/[0-9]+))?)|tasks(?:/(?:stats|"+id+"(?:/(?:logs|events|cancel|retry|wiki/retry-failed|graph/retry-failed))?))?|extractions/(?:documents|"+id+"(?:/(?:records|coverage|export\\.xlsx))?))")
            ||path.matches("/qa/(?:sessions(?:/"+id+"(?:/messages)?)?|messages/"+id+"/(?:retry|stop|events))")
            ||path.matches("/(?:search(?:/(?:keyword|vector|hybrid|graph|wiki|image-text|image-vector|multi|query-images))?|models(?:/(?:discover|test|"+id+"(?:/(?:test|test-file))?))?|model-connections(?:/"+id+")?|settings/[a-z-]+|system/(?:status|version|infrastructure|initialization)|capabilities|file-formats|parser-engines(?:/check)?|image-pipelines(?:/validate)?|processing-config/(?:suggest|resolve)|chunker/preview|graph-templates)");
    }
    private void authorize(Grant g,String method,String path,JsonNode body){
        if(!allowedRoute(method,path))throw new ApiException(404,"V101 接口未开放");boolean write=!readCall(method,path);String[] p=path.substring(1).split("/");String kind=p[0];
        if("knowledge-bases".equals(kind)){if(p.length==1){if(write&&!bool(g.c.get("published")))throw new ApiException(403,"此连接未开放新建");}else{g.kb(p[1],write);if(write&&"DELETE".equals(method)&&p.length==2)access.unused(g.c,p[1]);}}
        else if(Arrays.asList("knowledge","sources","images","preview-assets","uploads","tasks","extractions").contains(kind)){
            if("sources".equals(kind)&&p.length==2&&"resolve-batch".equals(p[1])){for(JsonNode id:body.path("source_ref_ids"))g.kb(resourceKB(g,"sources",id.asText()),false);}
            else if(p.length>1&&!Arrays.asList("policy","stats","documents").contains(p[1]))g.kb(resourceKB(g,kind,p[1]),write);
        }else if("qa".equals(kind)){
            if(p.length>=3){owned(g,"sessions".equals(p[1])?"qa-session":"qa-message",p[2]);}
            bodyScopes(g,body);if(write&&"sessions".equals(p[1])&&(p.length==2||"PATCH".equals(method))&&g.scopes.isEmpty())throw new ApiException(422,"问答必须限定已授权知识库");
        }else if("search".equals(kind)){bodyScopes(g,body);if(body.hasNonNull("query_image_id"))owned(g,"query-image",body.path("query_image_id").asText());if(!path.equals("/search/query-images")&&g.scopes.isEmpty())throw new ApiException(422,"检索必须限定已授权知识库");}
        else if(kind.equals("models")){if(write)g.administrator();}
        else if(kind.equals("model-connections"))g.administrator();
        else if(kind.equals("settings")){if(write||!Arrays.asList("appearance","parser-defaults","wiki-defaults","media-defaults","preview-defaults","retrieval-defaults","qa-defaults","extraction-defaults","model-bindings").contains(p[1]))g.administrator();}
        else if(kind.equals("system")){if(!Arrays.asList("status","version").contains(p[1]))g.administrator();}
        else if(path.equals("/parser-engines/check"))g.administrator();
        bodyScopes(g,body);
        if(body.has("config")&&!access.admin(g.actor))checkConfig(body.path("config"));
        if(path.startsWith("/processing-config/")&&body.has("overrides")&&!access.admin(g.actor))checkConfig(body.path("overrides"));
    }
    private void checkConfig(JsonNode config){if(!config.isObject())throw new ApiException(422,"配置须为对象");for(String k:Arrays.asList("base_url","endpoint","api_key","storage","storage_config","parser-engines"))if(config.has(k))throw new ApiException(403,"此配置仅管理员可维护");}
    private boolean visibleRow(Grant g,String path,JsonNode row){try{if(path.equals("/qa/sessions")){owned(g,"qa-session",row.path("id").asText(""));return true;}String kb=row.path("knowledge_base_id").asText("");if(kb.isEmpty()&&path.equals("/tasks"))kb=row.path("config").path("knowledge_base_id").asText("");if(kb.isEmpty()&&!row.path("knowledge_id").asText("").isEmpty())kb=resourceKB(g,"knowledge",row.path("knowledge_id").asText(""));if(kb.isEmpty()&&!row.path("id").asText("").isEmpty()&&path.equals("/extractions/documents"))kb=resourceKB(g,"knowledge",row.path("id").asText(""));return !kb.isEmpty()&&access.allowed(g.actor,g.c,kb,false);}catch(ApiException denied){if(denied.status==403||denied.status==404)return false;throw denied;}}
    private JsonNode listing(Grant g,String path,Map<String,String[]> query){return listing(g,path,query,false);}
    private JsonNode listing(Grant g,String path,Map<String,String[]> query,boolean every){ArrayNode all=json.createArrayNode();if(path.equals("/knowledge-bases")){String q=parameter(query,"q","").toLowerCase(Locale.ROOT);for(String id:permitted(g.actor,g.c)){try{JsonNode n=get(g.c,"/knowledge-bases/"+segment(id));if(q.isEmpty()||n.path("name").asText().toLowerCase(Locale.ROOT).contains(q))all.add(n);}catch(ApiException absent){if(absent.status!=404)throw absent;}}}else{if(permitted(g.actor,g.c).isEmpty())return page(all,query);String state=parameter(query,"state","");for(int p=1;p<=100;p++){String url=path+"?page="+p+"&page_size=100"+(state.isEmpty()?"":"&state="+segment(state));JsonNode raw=driver.client.execute(string(g.c,"endpoint"),knowledge.headers(g.c),s->s.request("GET",url,null));JsonNode rows=data(raw);for(JsonNode n:rows)if(visibleRow(g,path,n))all.add(n);if(!raw.path("meta").path("has_more").asBoolean()&&rows.size()<100)break;if(p==100)throw new ApiException(502,"V101 列表超过安全分页预算，请缩小查询范围");}}return every?json.valueToTree(map("success",true,"data",all)):page(all,query);}
    private JsonNode page(ArrayNode all,Map<String,String[]> query){int p=number(parameter(query,"page","1"),1,1000000),size=number(parameter(query,"page_size","20"),1,100);ArrayNode out=json.createArrayNode();for(int i=(p-1)*size;i<Math.min(p*size,all.size());i++)out.add(all.get(i));return json.valueToTree(map("success",true,"data",out,"meta",map("page",p,"page_size",size,"total",all.size(),"has_more",p*size<all.size())));}
    static String parameter(Map<String,String[]> q,String key,String fallback){String[] n=q.get(key);return n==null||n.length==0?fallback:n[0];}
    private static int number(String s,int min,int max){try{int n=Integer.parseInt(s);if(n<min||n>max)throw new NumberFormatException();return n;}catch(NumberFormatException e){throw new ApiException(422,"分页范围无效");}}
    private void complete(Grant g,String method,String path,JsonNode body,JsonNode response){JsonNode d=data(response);if(method.equals("POST")&&(path.equals("/knowledge-bases")||path.matches("/knowledge-bases/[^/]+/duplicate")))access.register(g.c,text(d,"id",512,true),g.actor);
        // Async deletion retains the original access record for task status, cancellation and audit. Missing remote libraries are omitted from lists.
        if(method.equals("DELETE")&&path.matches("/knowledge-bases/[^/]+")&&!d.hasNonNull("task_id")){String kb=path.split("/")[2];Map<String,Object> lib=access.library(g.c,kb);if(lib!=null){access.jdbc().update("DELETE FROM nw_knowledge_library_access WHERE library_id=?",lib.get("id"));access.jdbc().update("DELETE FROM nw_knowledge_library WHERE id=?",lib.get("id"));}}
        if(path.equals("/qa/sessions")&&method.equals("POST")||path.matches("/qa/sessions/[^/]+")&&method.equals("PATCH"))save(g,"qa-session",d.path("id").asText(),null);
        if(path.matches("/qa/sessions/[^/]+/messages")&&method.equals("POST")){String parent=path.split("/")[3];save(g,"qa-message",d.path("assistant_message_id").asText(),parent);save(g,"qa-message",d.path("user_message_id").asText(),parent);}
        if(path.matches("/qa/messages/[^/]+/retry")){Map<String,Object> row=access.one("SELECT parent_id FROM nw_knowledge_v101_resource WHERE service_key=? AND owner_id=? AND kind='qa-message' AND remote_id=?",access.serviceKey(g.c),g.actor,path.split("/")[3]);String parent=row==null?null:string(row,"parent_id");save(g,"qa-message",d.path("assistant_message_id").asText(),parent);save(g,"qa-message",d.path("user_message_id").asText(),parent);}
        if(path.equals("/search/query-images"))save(g,"query-image",d.path("query_image_id").asText(d.path("id").asText()),null);
    }
    private JsonNode sanitize(Grant g,String path,JsonNode raw){JsonNode result=raw.deepCopy();if(path.startsWith("/models")&&!access.admin(g.actor)){JsonNode d=data(result);java.util.function.Function<JsonNode,JsonNode> safe=n->{ObjectNode out=json.createObjectNode();for(String k:Arrays.asList("id","name","purpose","model_name","dimension"))if(n.has(k))out.set(k,n.get(k));return out;};if(d.isArray()){ArrayNode out=json.createArrayNode();for(JsonNode n:d)out.add(safe.apply(n));((ObjectNode)result).set("data",out);}else ((ObjectNode)result).set("data",safe.apply(d));}if(path.equals("/system/status")&&!access.admin(g.actor))((ObjectNode)result).set("data",json.valueToTree(map("ready",data(raw).path("ready"),"stage",data(raw).path("stage"))));if(!access.admin(g.actor))NebulaeV100RestDriver.scrub(result);return result;}
    JsonNode call(String actor,String connection,String method,String path,JsonNode body,String key){Map<String,Object> c=connection(actor,connection);Grant grant=new Grant(actor,c);String route=path.contains("?")?path.substring(0,path.indexOf('?')):path;authorize(grant,method,route,body);Map<String,Object> receipt=null;if(!readCall(method,route)){ObjectNode identity=json.valueToTree(map("method",method,"path",path,"body",body));ObjectNode safeIdentity=identity.deepCopy();NebulaeV100RestDriver.scrub(safeIdentity);receipt=operations.beginWithRequest(actor,connection,grant.scopes.isEmpty()?"":grant.scopes.iterator().next(),key,"v101.request",identity,safeIdentity);if(!Boolean.TRUE.equals(receipt.get("claimed"))){JsonNode saved=operations.result(receipt);if(saved==null)throw new ApiException(409,"原操作结果尚不明确，请先核对，禁止重复提交");complete(grant,method,route,body,saved);operations.finish(string(receipt,"id"));return sanitize(grant,route,saved);}}
        Map<String,String> headers=knowledge.headers(c);if(key!=null&&!key.isEmpty())headers.put("Idempotency-Key",key);JsonNode response=driver.client.execute(string(c,"endpoint"),headers,s->s.request(method,path,Arrays.asList("GET","HEAD").contains(method)||body.isNull()?null:body));
        if(receipt!=null){operations.received(string(receipt,"id"),response);complete(grant,method,route,body,response);operations.finish(string(receipt,"id"));knowledge.audit(actor,connection,"v101.request",map("path",path,"operationId",receipt.get("id")));}return sanitize(grant,route,response);
    }
    Object recover(String actor,String operation){Map<String,Object> row=operations.owned(actor,operation),c=connection(actor,string(row,"connection_id"));JsonNode saved=operations.result(row);if(saved==null)throw new ApiException(409,"原操作结果尚不明确，请先核对远端内容，禁止自动重发");if("document.upload".equals(row.get("operation"))){access.require(actor,c,string(row,"collection_id"),true);}else{try{JsonNode identity=json.readTree(string(row,"request_json"));Grant grant=new Grant(actor,c);String path=identity.path("path").asText(),route=path.contains("?")?path.substring(0,path.indexOf('?')):path;authorize(grant,identity.path("method").asText(),route,identity.path("body"));complete(grant,identity.path("method").asText(),route,identity.path("body"),saved);}catch(IOException e){throw new ApiException(500,"原操作记录无效");}}operations.finish(operation);return map("result",saved,"operationId",operation);}
    void serve(String actor,String connection,String tail,HttpServletRequest request,HttpServletResponse response)throws IOException{
        Map<String,Object> c=connection(actor,connection);String base=request.getRequestURI().substring(0,request.getRequestURI().length()-tail.length());
        if(tail.startsWith("ui/")||tail.equals("ui")){
            String file=tail.substring(2);if(file.startsWith("/assets/")||file.startsWith("/pdfjs/")){KnowledgeRestClient.Binary binary=driver.client.execute(string(c,"endpoint"),knowledge.headers(c),s->s.rootDownload(file));response.setContentType(binary.contentType);response.getOutputStream().write(binary.bytes);return;}
            KnowledgeRestClient.Binary index=driver.client.execute(string(c,"endpoint"),knowledge.headers(c),s->s.rootDownload("/"));String config=json.writeValueAsString(map("apiBase",base+"api/v1","uiBase",base+"ui","admin",access.admin(actor),"canCreate",bool(c.get("published")),"connectionId",connection)).replace("<","\\u003c");String boot="<script>window.__NEBUWORK_V101__="+config+";(()=>{const c=window.__NEBUWORK_V101__,m='/api/knowledge-v101/'+encodeURIComponent(c.connectionId)+'/ui',i=location.pathname.indexOf(m);if(i<0)throw Error('Invalid V101 location');c.uiBase=location.pathname.slice(0,i)+m;c.apiBase=c.uiBase.slice(0,-3)+'/api/v1';const b=document.createElement('base');b.href=c.uiBase+'/';document.head.append(b);})()</script>";String html=new String(index.bytes,StandardCharsets.UTF_8).replace("<head>","<head>"+boot);response.setContentType("text/html;charset=UTF-8");response.setHeader("Content-Security-Policy","frame-ancestors 'self'; object-src 'none'");response.getWriter().write(html);return;
        }
        if(!tail.startsWith("api/v1/"))throw new ApiException(404,"V101 路径不存在");String path="/"+tail.substring(7);if(path.contains("%")||path.contains("..")||path.contains("\\"))throw new ApiException(422,"无效 V101 路径");String method=request.getHeader("X-Knowledge-Method");if(method==null)method=request.getMethod();else if(!request.getMethod().equals("POST"))throw new ApiException(422,"写方法只能通过 POST 传递");
        boolean raw=request.getContentType()!=null&&!request.getContentType().startsWith("application/json")&&!Arrays.asList("GET","HEAD").contains(method);JsonNode body=json.createObjectNode();if(!raw&&!Arrays.asList("GET","HEAD").contains(method)){byte[] bytes=read(request.getInputStream(),2*1024*1024);if(bytes.length>0)body=json.readTree(bytes);}
        Grant grant=new Grant(actor,c);authorize(grant,method,path,body);
        String query=request.getQueryString(),target=path+(query==null?"":"?"+query);if(query!=null&&(query.contains("#")||query.length()>16384))throw new ApiException(422,"查询参数无效");
        if(method.equals("GET")&&Arrays.asList("/knowledge-bases","/tasks","/extractions/documents","/qa/sessions").contains(path)){write(response,rewrite(listing(grant,path,request.getParameterMap()),base));return;}
        if(path.equals("/tasks/stats")){JsonNode rows=listing(grant,"/tasks",Collections.emptyMap(),true);Map<String,Integer> counts=new LinkedHashMap<>();for(JsonNode t:data(rows))counts.merge(t.path("state").asText(),1,Integer::sum);ArrayNode out=json.createArrayNode();counts.forEach((k,v)->out.add(json.valueToTree(map("state",k,"count",v))));write(response,json.valueToTree(map("success",true,"data",out)));return;}
        boolean stream=path.endsWith("/events")||path.matches("/(?:preview-assets/[^/]+|images/[^/]+/content|knowledge/[^/]+/(?:preview|download)|extractions/[^/]+/export\\.xlsx)");
        if(stream){Map<String,String> headers=new HashMap<>();for(String h:Arrays.asList("Range","Last-Event-ID"))if(request.getHeader(h)!=null)headers.put(h,request.getHeader(h));String verb=method;driver.client.execute(string(c,"endpoint"),knowledge.headers(c),s->{s.forward(verb,target,false,null,-1,null,headers,response,()->grant.live(request));return null;});return;}
        if(raw){String key=request.getHeader("Idempotency-Key");if(key==null||key.isEmpty())throw new ApiException(422,"上传缺少幂等键");if(request.getContentLengthLong()>2147483648L)throw new ApiException(413,"上传超过 2 GiB");Map<String,String> headers=knowledge.headers(c);headers.put("Idempotency-Key",key);for(String header:Arrays.asList("X-Content-SHA256","Upload-Offset"))if(request.getHeader(header)!=null)headers.put(header,request.getHeader(header));String verb=method;JsonNode result=driver.client.execute(string(c,"endpoint"),headers,s->{try{if(request.getContentType().startsWith("multipart/form-data"))return s.multipart(verb,target,request.getParts());return s.rawJSON(verb,target,request.getInputStream(),request.getContentLengthLong(),request.getContentType());}catch(javax.servlet.ServletException e){throw new ApiException(422,"无效 multipart 上传");}catch(IOException e){throw new ApiException(422,"上传内容读取失败");}});complete(grant,method,path,body,result);write(response,rewrite(sanitize(grant,path,result),base));return;}
        String key=request.getHeader("Idempotency-Key");JsonNode result=call(actor,connection,method,target,body,key);write(response,rewrite(result,base));
    }
    private JsonNode rewrite(JsonNode n,String base){return n;}
    static byte[] read(InputStream input,int max)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=input.read(b))!=-1){if(out.size()+n>max)throw new ApiException(413,"请求过大");out.write(b,0,n);}return out.toByteArray();}
    private void write(HttpServletResponse response,JsonNode n)throws IOException{response.setContentType("application/json;charset=UTF-8");json.writeValue(response.getOutputStream(),n);}
}

@RestController
@RequestMapping("/api/knowledge-v101")
class KnowledgeV101Controller {
    private final KnowledgeV101Gateway gateway;KnowledgeV101Controller(KnowledgeV101Gateway gateway){this.gateway=gateway;}
    @RequestMapping("/{connection}/**") public void serve(@PathVariable String connection,HttpServletRequest request,HttpServletResponse response)throws IOException{String prefix="/api/knowledge-v101/"+connection+"/";String path=request.getRequestURI().substring(request.getContextPath().length());int index=path.indexOf(prefix);if(index!=0)throw new ApiException(404,"V101 路径不存在");gateway.serve(RequestIdentity.actor(request),connection,path.substring(prefix.length()),request,response);}
}
